{"path": "/tmp/sv-fd7187d5eea84e3f97d5ae8eac35ef72/Components/Pages/Apply/ReviewStep.razor", "file_text": "@namespace sv_fd7187d5eea84e3f97d5ae8eac35ef72.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation-box">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is:</p>
            <strong class="application-id">@ApplicationId</strong>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email | @r.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfoModel Personal { get; set; } = new();
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    public bool IsSubmitting { get; set; }
    public bool IsSubmitted { get; set; }
    public int ApplicationId { get; set; }

    public void ShowConfirmation(int applicationId)
    {
        IsSubmitting = false;
        IsSubmitted = true;
        ApplicationId = applicationId;
        StateHasChanged();
    }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        await OnSubmit.InvokeAsync();
    }
}
"}

