@page "/apply"
@using sv_fd7187d5eea84e3f97d5ae8eac35ef72.Models
@using sv_fd7187d5eea84e3f97d5ae8eac35ef72.Services
@namespace sv_fd7187d5eea84e3f97d5ae8eac35ef72.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedUpTo="@completedUpTo"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personal.FullName"
                              Email="@personal.Email"
                              Phone="@personal.Phone"
                              Address="@personal.Address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnEntriesChanged="entries => workEntries = entries"
                             OnNext="() => AdvanceStep()"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnReferencesChanged="refs => references = refs"
                            OnNext="() => AdvanceStep()"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="val => coverLetter = val"
                             OnNext="HandleCoverLetterNext"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep @ref="reviewStepRef"
                        Personal="@personal"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="() => GoToStep(3)"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private int completedUpTo = 0;
    private ReviewStep? reviewStepRef;

    private PersonalInfoModel personal = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        if (step <= completedUpTo)
        {
            currentStep = step;
        }
    }

    private void AdvanceStep()
    {
        currentStep++;
        if (completedUpTo < currentStep)
            completedUpTo = currentStep;
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        personal = new PersonalInfoModel
        {
            FullName = data.FullName,
            Email = data.Email,
            Phone = data.Phone,
            Address = data.Address
        };
        AdvanceStep();
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        AdvanceStep();
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(
            new PersonalInfo(personal.FullName, personal.Email, personal.Phone, personal.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        var id = await ApplicationService.SubmitApplicationAsync(application);
        reviewStepRef?.ShowConfirmation(id);
    }
}

